    pg.goto(U + '#express-pause'); pg.locator('[data-action="xp-ready"][data-v="ready"]').click(); pg.wait_for_timeout(200); check(pg.locator('[data-action="xp-intent"]').count() == 0, 'the take-your-time situation asks for a pause first')
    pg.goto(U + '#prefs'); pg.wait_for_timeout(1200); pg.check('#aiConsent')
