    pg.fill('#xpText', 'Mondays, people are tired, and the coffee machine.'); pg.evaluate("(()=>{const t=document.getElementById('xpText'); t.dataset.spoken='1'; t.dispatchEvent(new Event('input',{bubbles:true}));})()")
