    op.locator('[data-action="xp-ready"][data-v="ready"]').click(); op.locator('[data-action="xp-intent"][data-v="share"]').click(); op.fill('#xpText', 'Last year I decided to leave a stable job because'); op.clock.run_for(26000); op.wait_for_selector('.interrupt')
    check('What were you saying?' in op.inner_text('.interrupt') and op.input_value('#xpText').startswith('Last year'), 'the recovery situation interrupts mid-answer and keeps what was written'); c2.close()
